#!/usr/bin/env bash

# Repo-tracked Android environment loader.
# `.tooling/` remains disposable local state; this script defines the stable
# interface and optionally loads a local override generated by the installer.

_eiel_android_env_dir="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
_eiel_android_repo_root="$(cd "${_eiel_android_env_dir}/../.." && pwd)"
_eiel_android_tooling_dir="${_eiel_android_repo_root}/.tooling"
_eiel_android_local_override="${_eiel_android_tooling_dir}/android-env.local.sh"
_eiel_android_legacy_override="${_eiel_android_tooling_dir}/android-env.sh"

_eiel_android_prepend_path() {
  local dir="$1"
  if [[ -z "${dir}" ]] || [[ ! -d "${dir}" ]]; then
    return 0
  fi
  case ":${PATH:-}:" in
    *":${dir}:"*) ;;
    *) export PATH="${dir}${PATH:+:${PATH}}" ;;
  esac
}

if [[ -f "${_eiel_android_local_override}" ]]; then
  # shellcheck disable=SC1090
  source "${_eiel_android_local_override}"
elif [[ -f "${_eiel_android_legacy_override}" ]]; then
  # Compatibility path for older local installs. New installs write
  # `.tooling/android-env.local.sh` instead.
  # shellcheck disable=SC1090
  source "${_eiel_android_legacy_override}"
fi

export EIEL_REPO_ROOT="${_eiel_android_repo_root}"
export EIEL_ANDROID_TOOLING_DIR="${_eiel_android_tooling_dir}"

if [[ -z "${JAVA_HOME:-}" ]]; then
  export JAVA_HOME="${_eiel_android_tooling_dir}/jdk-17"
fi
if [[ -z "${ANDROID_SDK_ROOT:-}" ]]; then
  export ANDROID_SDK_ROOT="${_eiel_android_tooling_dir}/android-sdk"
fi
if [[ -z "${ANDROID_HOME:-}" ]]; then
  export ANDROID_HOME="${ANDROID_SDK_ROOT}"
fi
if [[ -z "${JDK_HOME:-}" ]] && [[ -n "${JAVA_HOME:-}" ]]; then
  export JDK_HOME="${JAVA_HOME}"
fi

if [[ -d "${_eiel_android_tooling_dir}/gradle-home" ]]; then
  export GRADLE_USER_HOME="${_eiel_android_tooling_dir}/gradle-home"
else
  export GRADLE_USER_HOME="${_eiel_android_tooling_dir}/gradle-user-home"
fi

export ANDROID_USER_HOME="${_eiel_android_tooling_dir}/android-user-home"
export ANDROID_AVD_HOME="${ANDROID_USER_HOME}/avd"
export ANDROID_EMULATOR_HOME="${ANDROID_USER_HOME}"
unset ANDROID_PREFS_ROOT

_eiel_android_prepend_path "${ANDROID_SDK_ROOT}/platform-tools"
_eiel_android_prepend_path "${ANDROID_SDK_ROOT}/cmdline-tools/latest/bin"
_eiel_android_prepend_path "${JAVA_HOME}/bin"
